using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class RoadsideFarmyards {
 const string A="Assets/NewMap/FiveHangars/RoadsideFarmyards";static Vector3[] road;static float[] lengths;static Terrain terrain;static Transform root;static System.Random rng=new System.Random(4082);static List<CombineInstance> pieces=new List<CombineInstance>();static List<Vector3> positions=new List<Vector3>();static Mesh cube;
 static float H(Vector3 p)=>terrain.SampleHeight(p)+terrain.transform.position.y;
 static Vector3 Nearest(Vector3 p){float best=99999,s=0;for(int i=1;i<road.Length;i++){var a=new Vector2(road[i-1].x,road[i-1].z);var d=new Vector2(road[i].x-road[i-1].x,road[i].z-road[i-1].z);var q=new Vector2(p.x,p.z)-a;float t=Mathf.Clamp01(Vector2.Dot(q,d)/d.sqrMagnitude),v=(q-d*t).sqrMagnitude;if(v<best){best=v;s=Mathf.Lerp(lengths[i-1],lengths[i],t);}}return new Vector3(Mathf.Sqrt(best),s,0);}
 static Vector3 At(float s){int i=Array.FindIndex(lengths,v=>v>=s);i=Mathf.Clamp(i,1,road.Length-1);return Vector3.Lerp(road[i-1],road[i],Mathf.InverseLerp(lengths[i-1],lengths[i],s));}
 static void Piece(Vector3 p,Vector3 size,Quaternion rotation){positions.Add(p);pieces.Add(new CombineInstance{mesh=cube,transform=Matrix4x4.TRS(p,rotation,size)});}
 static bool Gate(Vector3 p){if(new Vector2(p.x,p.z-24).magnitude<40)return true;if(new Vector2(p.x-8,p.z-175).magnitude<35)return true;foreach(var c in new[]{new Vector3(55,0,112),new Vector3(-109,0,153),new Vector3(-94,0,233),new Vector3(62,0,206)})if(new Vector2(p.x-c.x,p.z-c.z).magnitude<21)return true;return false;}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");root=GameObject.Find("New_Map").transform;if(root.Find("13_Roadside_Farmyards"))throw new Exception("Already authored");terrain=root.GetComponentInChildren<Terrain>();Directory.CreateDirectory(A);AssetDatabase.Refresh();EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/FiveHangars/Gameplay.before-roadside-farms.unity",true);road=File.ReadAllLines("output/NewMap/Revision2/road-centerline.csv").Skip(1).Select(l=>{var s=l.Split(',');return new Vector3(float.Parse(s[0],System.Globalization.CultureInfo.InvariantCulture),0,float.Parse(s[2],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();lengths=new float[road.Length];for(int i=1;i<road.Length;i++)lengths[i]=lengths[i-1]+Vector3.Distance(road[i-1],road[i]);
 var td=terrain.terrainData;int n=td.alphamapWidth;var alpha=td.GetAlphamaps(0,0,n,n);int pixels=0;
 for(int z=0;z<n;z++)for(int x=0;x<n;x++){var p=terrain.transform.position+new Vector3(x/(float)(n-1)*td.size.x,0,z/(float)(n-1)*td.size.z);float rect=Mathf.Max(Mathf.Abs(p.x+58)-20,Mathf.Abs(p.z-159)-24);float blend=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,8,rect));if(blend<=0)continue;var near=Nearest(p);float width=Mathf.Clamp(3.4f+.7f*Mathf.Sin(near.y/38)+.48f*Mathf.Sin(near.y/17+.8f),2.8f,4.8f);float noise=(Mathf.PerlinNoise(p.x*.15f+80,p.z*.15f+30)-.5f)*.55f;float dirt=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(width,width+1.6f,near.x+noise));float grass=1-dirt,variation=Mathf.PerlinNoise(p.x*.06f+100,p.z*.06f+500);float[] desired={grass*(.55f+.3f*variation),dirt*.3f,dirt*.08f,0,grass*(.45f-.3f*variation),dirt*.02f,dirt*.6f};for(int l=0;l<td.alphamapLayers;l++)alpha[z,x,l]=Mathf.Lerp(alpha[z,x,l],desired[l],blend);pixels++;}td.SetAlphamaps(0,0,alpha);EditorUtility.SetDirty(td);
 var group=new GameObject("13_Roadside_Farmyards").transform;group.SetParent(root,false);Undo.RegisterCreatedObjectUndo(group.gameObject,"Roadside farms and village junction");var pCube=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=pCube.GetComponent<MeshFilter>().sharedMesh;Object.DestroyImmediate(pCube);int posts=0;
 for(int side=-1;side<=1;side+=2){Vector3 previous=Vector3.zero;bool lastValid=false;for(float s=42;s<lengths.Last()-8;s+=3.1f){var c=At(s);var tangent=At(Mathf.Min(s+1,lengths.Last()))-At(Mathf.Max(0,s-1));tangent.y=0;tangent.Normalize();var p=c+new Vector3(-tangent.z,0,tangent.x)*(side*(7.4f+.35f*Mathf.Sin(s/19)));p.y=H(p);bool valid=!Gate(p);if(valid){Piece(p+Vector3.up*.76f,new Vector3(.16f,1.52f,.16f),Quaternion.Euler(0,s%37,0));posts++;if(lastValid)foreach(float y in new[]{.55f,1.1f}){var d=p-previous;Piece((p+previous)*.5f+Vector3.up*y,new Vector3(.12f,.14f,d.magnitude),Quaternion.LookRotation(d));}}previous=p;lastValid=valid;}}
 var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/FiveHangars/FinishedShop/Oiled oak shop joinery.mat");int serial=0;
 AssetDatabase.StartAssetEditing();try{foreach(var cell in positions.Select((p,i)=>new{p,i}).GroupBy(q=>Mathf.FloorToInt(q.p.x/36)+"_"+Mathf.FloorToInt(q.p.z/36))){var mesh=new Mesh{name="Roadside fence "+cell.Key,indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(cell.Select(c=>pieces[c.i]).ToArray(),true,true);mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+"/Fence cell "+(++serial)+".asset");var g=new GameObject("Combined roadside fence "+cell.Key);g.transform.SetParent(group,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;g.AddComponent<MeshCollider>().sharedMesh=mesh;}}
 finally{AssetDatabase.StopAssetEditing();}
 var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Imported/Toon Series/Toon Farm Pack/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).GroupBy(Path.GetFileNameWithoutExtension).ToDictionary(g=>g.Key,g=>g.First());var atlas=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/FiveHangars/FinishedShop/Textured farm stock and cottage.mat");int placed=0;
 foreach(float s in new[]{95f,190f,305f,408f}){var c=At(s);var tangent=(At(s+1)-At(s-1)).normalized;int side=s<250?1:-1;var center=c+new Vector3(-tangent.z,0,tangent.x)*(side*12.3f);if(Gate(center))continue;var cluster=new GameObject("Roadside hay and supply bay "+s).transform;cluster.SetParent(group,false);for(int k=0;k<4;k++){string name=k<2?"TFP_Hay_Bale_01A":k==2?"TFP_Wooden_Pallet_01A":"TFP_Wooden_Crate_01A";var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(paths[name]),cluster);var p=center+new Vector3(tangent.x,0,tangent.z)*(k-1.5f)*1.6f;p.y=H(p);g.transform.SetPositionAndRotation(p,Quaternion.Euler(0,Mathf.Atan2(tangent.x,tangent.z)*Mathf.Rad2Deg+15*k,0));foreach(var r in g.GetComponentsInChildren<MeshRenderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>m.name.StartsWith("TFP_Atlas_1A")?atlas:m).ToArray();placed++;}}
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);Directory.CreateDirectory("output/NewMap/RoadsideFarmyards");string report=posts+" split-rail fence posts along both road shoulders, combined into "+serial+" spatial render/collision cells. Openings retained for farm plots, main yard and village approaches. "+placed+" hay/pallet/crate roadside props. Removed obsolete square market-garden dirt stamp near village; "+pixels+" terrain blend samples now follow a curved road with soft meadow shoulders. Road centerline/heights unchanged.";File.WriteAllText("output/NewMap/RoadsideFarmyards/summary.txt",report);return report;
 }
